import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"OmniRouter: Taming Model Chaos","description":"Why I built OmniRouter — turning model churn into a config file, with load balancing, failover and real streaming in one Go binary.","frontmatter":{"title":"OmniRouter: Taming Model Chaos","description":"Why I built OmniRouter — turning model churn into a config file, with load balancing, failover and real streaming in one Go binary."},"headers":[],"relativePath":"en/vibe-stories/story-1/index.md","filePath":"en/vibe-stories/story-1/index.md"}`),a={name:`en/vibe-stories/story-1/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="omnirouter-taming-model-chaos" tabindex="-1">OmniRouter: Taming Model Chaos <a class="header-anchor" href="#omnirouter-taming-model-chaos" aria-label="Permalink to “OmniRouter: Taming Model Chaos”">​</a></h1><p>The AI ecosystem moves at scroll speed. The model that powered my app on Monday is deprecated by Friday, prices flip overnight, free tiers appear and vanish. My projects kept breaking for reasons that had nothing to do with my code — so I made the churn someone else&#39;s problem. That someone is <strong><a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a></strong>.</p><h2 id="one-endpoint-many-brains" tabindex="-1">One endpoint, many brains <a class="header-anchor" href="#one-endpoint-many-brains" aria-label="Permalink to “One endpoint, many brains”">​</a></h2><p>OmniRouter sits between your app and every model provider you use. Your code speaks plain OpenAI — one base URL, one API key, standard <code>/v1/chat/completions</code> — and the router decides which brain actually answers: GLM, Qwen, DeepSeek or any custom OpenAI-compatible endpoint you register. Switching a model becomes a <strong>config change, not a refactor</strong>.</p><h2 id="the-parts-that-took-real-engineering" tabindex="-1">The parts that took real engineering <a class="header-anchor" href="#the-parts-that-took-real-engineering" aria-label="Permalink to “The parts that took real engineering”">​</a></h2><ul><li><strong>Load balancing that understands health</strong> — weighted routing with health checks; a provider that fails its probe is cooled down and routed around in milliseconds.</li><li><strong>Failover without lying to the client</strong> — if a request dies mid-flight on provider A, the router retries on provider B, and the caller just sees a slightly slower 200.</li><li><strong>Real streaming, end to end</strong> — SSE tokens flow through the router untouched, because a proxy that buffers streams is not a proxy, it is a bottleneck.</li><li><strong>One static binary</strong> — pure Go, stdlib-first, cross-compiled: <code>./omnirouter</code> is the whole deployment story.</li></ul><h2 id="what-it-proves" tabindex="-1">What it proves <a class="header-anchor" href="#what-it-proves" aria-label="Permalink to “What it proves”">​</a></h2><p>OmniRouter is the backbone of my own AI stack — it fronts every model my agent tooling touches, and it ships inside <a href="/Usf/en/projects/hermes-stack/">Hermes Stack</a> as part of a one-click AI server. It shows I can design API infrastructure the way production systems need it: stateless cores, observable request paths, and failure treated as a first-class case — not an afterthought.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};